#include <vector>
#include PERIPHERAL_LCD_HEADER
#include "frame_helpers.h"
struct WireLcd {char cells[32];uint8_t address=0;WireLcd(){memset(cells,' ',32);}void transfer(Peripheral::Lcd& lcd,uint32_t now){TWSR=8;TWCR=_BV(TWINT);lcd.poll(now);CHECK(TWDR==(PERIPHERAL_LCD_ADDRESS<<1));TWSR=0x18;TWCR=_BV(TWINT);lcd.poll(now);std::vector<uint8_t> data;while(!(TWCR&_BV(TWSTO))){CHECK(data.size()<6);data.push_back(uint8_t(TWDR));TWSR=0x28;TWCR=_BV(TWINT);lcd.poll(now);}if(data.size()==6){CHECK((data[0]&4)==0&&(data[1]&4)&&(data[2]&4)==0);CHECK((data[3]&4)==0&&(data[4]&4)&&(data[5]&4)==0);uint8_t v=uint8_t((data[0]&0xf0)|(data[3]>>4));if(data[0]&1){uint8_t pos=address<16?address:address>=0x40&&address<0x50?address-0x40+16:255;CHECK(pos<32);cells[pos]=char(v);address++;}else if(v&0x80)address=v&0x7f;else if(v==1){memset(cells,' ',32);address=0;}}TWCR&=uint8_t(~_BV(TWSTO));lcd.poll(now);}void advance(Peripheral::Lcd& lcd,Peripheral::Engine& e,uint32_t from,uint32_t to){for(uint32_t t=from;t<to;t++){lcd.display(e,t);lcd.poll(t);if(lcd.busy())transfer(lcd,t);}CHECK(!lcd.fault());}void row(const char* expected){if(memcmp(cells,expected,16)){fprintf(stderr,"LCD expected [%.16s], actual [%.16s]\n",expected,cells);std::exit(1);}}};
static void send(Peripheral::Engine& e,const Proto::Frame& q,uint32_t at){Proto::Frame r;e.handle(q,r,at);CHECK(Proto::op(r)==Proto::ACK||Proto::op(r)==Proto::PERIPHERAL_META);}
int main(){Peripheral::Engine e;Peripheral::Lcd lcd;WireLcd wire;lcd.setup(0);send(e,hello(),0);send(e,policy(2,1,1),0);send(e,stop(3,1),0);wire.advance(lcd,e,0,150);wire.row("DIST:---.-cm N/A");CHECK(wire.cells[30]=='B');
 const uint16_t mm[]={100,199,200,250,4000};const char* rows[]={"DIST: 10.0cm STP","DIST: 19.9cm STP","DIST: 20.0cm STP","DIST: 25.0cm OK ","DIST:400.0cm OK "};uint32_t t=150;for(uint8_t i=0;i<5;i++){send(e,telemetry(4+i,1,10+i,mm[i],0,i<3?19:3),t);wire.advance(lcd,e,t,t+100);wire.row(rows[i]);t+=100;}
 send(e,telemetry(10,1,20,0,0,5),t);wire.advance(lcd,e,t,t+100);wire.row("DIST:---.-cm ERR");t+=100;send(e,telemetry(11,1,21,0,0,0),t);wire.advance(lcd,e,t,t+100);wire.row("DIST:---.-cm N/A");t+=100;
 send(e,telemetry(12,1,22,250,150,3),t);wire.advance(lcd,e,t,t+130);wire.row("DIST: 25.0cm STA");t+=130;
 send(e,batch(13,1,{3,8}),t);Proto::SharedState s={100,1,1,13,1,1,5,5,0,true,128};send(e,sync(s),t);wire.advance(lcd,e,t,t+100);CHECK(wire.cells[18]=='F'&&wire.cells[22]=='1'&&wire.cells[26]=='1');t+=100;
 send(e,policy(14,2,0),t);wire.advance(lcd,e,t,t+100);CHECK(wire.cells[18]=='?'&&wire.cells[22]=='0'&&wire.cells[26]=='0'&&wire.cells[30]=='Y');
 puts("PASS decoded PCF8574 LCD writes: five distance boundaries, ERR/N/A/stale, local outputs, inhibited stale motor observation");}
